/**
 * Checkout Branch Pre-CLI Action
 * Creates or checks out the feature branch for the ticket before the CLI agent runs.
 * Branch name format: ai/<TICKET-KEY>
 * If the branch already exists (locally or remotely), it is checked out directly.
 * postAction (developTicketAndCreatePR) then just commits and pushes the current branch.
 *
 * Two-branch mode (config.git.featureBranch.enabled): when the "feature" branch doesn't
 * exist yet remotely, customParams.branchCreateFnPath can point to a JS file (module.exports
 * = function(ctx)) that creates it by some project-specific mechanism instead of a plain
 * `git push -u origin` — e.g. a repo whose branch-protection rules block direct pushes for
 * that branch pattern and require going through an external CI job. See loadHookFn() in
 * configLoader.js for the loading contract. When not configured, behavior is unchanged.
 */

const { GIT_CONFIG } = require('./config.js');
var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var branchSetup = require('./common/branchSetup.js');
var gitStaging = require('./common/gitStaging.js');

// Adapter matching the (command, workingDir) signature of the
// common/pullRequest.js probe helpers (gh-912) — this action always runs in
// the job root, so workingDir stays unset.
function runCommandForProbes(command) {
    return cli_execute_command({ command: command });
}

// ── gh-1190: checkoutBranch seam split ──────────────────────────────────────
// Mirrors the preCliDevelopmentSetup.js gh-1042 extraction pattern: pure
// route decisions plus small side-effecting clusters keep action() linear;
// the exact commands, log lines and their order are unchanged
// (characterization tests: js/unit-tests/test_checkoutBranch.js).

/** Pure: customParams resolution for both Teammate and standalone runs. */
function resolveActionCustomParams(params) {
    return (params.jobParams && params.jobParams.customParams) || params.customParams || {};
}

/** Best-effort git author configuration — failures are warnings only. */
function configureGitAuthor(config) {
    branchSetup.configureGitAuthor(runCommandForProbes, config, true);
}

// Fetch latest remote state — target branch only (owner 2026-10-03:
// blanket fetches are banned; feature-branch checks use ls-remote).
function fetchTargetBranch(config) {
    branchSetup.fetchBranchRefs(prHelper, runCommandForProbes, [config.git.baseBranch], 'Could not fetch remote branches:');
    console.log('Fetched target branch:', config.git.baseBranch);
}

/**
 * `git branch --list` capture for `branchName`, cleaned of wrapper artifacts.
 * `warnMessage` (optional) is logged with the error when the probe fails —
 * pass null for the silent two-branch feature probes.
 */
function readLocalBranchList(branchName, warnMessage) {
    return branchSetup.readLocalBranchList(prHelper, runCommandForProbes, branchName, warnMessage);
}

/** Strict ls-remote existence probe (gh-912) — `warnMessage` optional. */
function probeRemoteBranch(branchName, warnMessage) {
    return branchSetup.probeRemoteBranch(prHelper, runCommandForProbes, null, branchName, warnMessage);
}

/** Plain (no-hook) two-branch feature creation tail for this action. */
function createFeatureBranchPlain(config, featureBranchName) {
    cli_execute_command({ command: 'git checkout ' + config.git.baseBranch });
    cli_execute_command({ command: 'git pull origin ' + config.git.baseBranch });
    cli_execute_command({ command: 'git checkout -b ' + featureBranchName });
    cli_execute_command({ command: 'git push -u origin ' + featureBranchName });
}

/**
 * Two-branch mode: make the feature branch exist — via the configured
 * branchCreateFnPath hook (project-specific mechanism, e.g. an external CI
 * job; the hook is responsible for making the branch exist on origin, so it
 * is fetched and checked out like any other pre-existing remote branch) or a
 * plain base-branch checkout + push when no hook is configured.
 */
function createFeatureBranch(config, customParams, ticket, featureBranchName) {
    branchSetup.createFeatureBranch(prHelper, configLoader, runCommandForProbes, config, customParams, ticket, featureBranchName, function (name) {
        createFeatureBranchPlain(config, name);
    });
}

/**
 * Two-branch mode: ensure the feature branch exists and check it out.
 * Returns the feature branch name — the dev branch is created from it.
 */
function establishFeatureBranch(config, customParams, ticket) {
    return branchSetup.establishFeatureBranch(prHelper, configLoader, runCommandForProbes, null, config, customParams, ticket, function (name) {
        createFeatureBranchPlain(config, name);
    });
}

/**
 * gh-1301: drop untracked input/ per-run artifacts before the dev-branch
 * checkout. Since gh-1318 the fresh regenerated input/ is stashed aside
 * (branchSetup.stashFreshInput) BEFORE this runs, so the clean can no longer
 * destroy the reporter's answer — it now only ever sweeps leftovers when the
 * stash itself failed (and otherwise no-ops while input/ is away). input/ is
 * a per-run artifact drop — remove untracked collisions (tracked files are
 * untouched) so the re-run aligns with the existing branch, mirroring the
 * .codegraph guard pattern. Best-effort: removal failures warn and never
 * block the checkout.
 *
 * The command is a CONSTANT: `git clean -fd -- input/` deletes untracked
 * files/directories under input/ (no -x, so ignored files are untouched).
 * Nothing from `git status` is parsed or interpolated — porcelain C-quotes
 * non-trivial names (`?? "input/bad name.md"`), so a parse + `rm -rf`
 * loop both no-oped on exactly the attachment-style names most likely to
 * collide and embedded ticket-controlled bytes into a shell string
 * (review round 1, blocking).
 */
function dropUntrackedInputArtifacts() {
    try {
        runCommandForProbes('git clean -fd -- input/');
    } catch (e) {
        console.warn('Input-artifact cleanup before checkout failed:', e);
    }
}

/**
 * gh-1318 root-cause heal (canonical copy: branchSetup.healLegContextArtifacts),
 * run right after a successful dev-branch checkout: seed input//outputs into
 * .git/info/exclude and untrack what the branch already carries — both
 * best-effort.
 */
function healLegContextArtifacts() {
    branchSetup.healLegContextArtifacts(runCommandForProbes, gitStaging.untrackLegContextArtifacts);
}

/**
 * Dev-branch checkout decision tree only — stash/restore/heal live in
 * checkoutDevBranch so every route is wrapped. Exists locally → plain
 * checkout; exists on remote → tracking checkout; absent → create from
 * branchBase.
 */
function runDevBranchCheckoutDecisionTree(branchName, branchBase) {
    var localBranches = readLocalBranchList(branchName, 'Error checking local branches:');
    if (localBranches.trim()) {
        // Branch exists locally — check it out
        console.log('Branch exists locally, checking out:', branchName);
        cli_execute_command({ command: 'git checkout ' + branchName });
        return;
    }

    var remoteBranchExists = probeRemoteBranch(branchName, 'Error checking remote branches:');
    if (remoteBranchExists) {
        // Exists on remote — checkout tracking remote
        console.log('Branch exists on remote, checking out with tracking:', branchName);
        cli_execute_command({ command: 'git checkout -b ' + branchName + ' origin/' + branchName });
        return;
    }

    // New branch — start from base branch (or feature branch in two-branch mode)
    console.log('Creating new branch from', branchBase + ':', branchName);
    cli_execute_command({ command: 'git checkout ' + branchBase });
    cli_execute_command({ command: 'git pull origin ' + branchBase });
    cli_execute_command({ command: 'git checkout -b ' + branchName });
}

function checkoutDevBranch(branchName, branchBase) {
    // gh-1318: the freshly regenerated input/ IS the current truth — stash it
    // aside so neither the clean below nor the checkout can destroy it, then
    // restore it over any branch-tracked stale copy. Restore runs in finally:
    // a failed checkout must still give the fresh input back.
    var stashed = branchSetup.stashFreshInput(runCommandForProbes);
    dropUntrackedInputArtifacts();

    try {
        runDevBranchCheckoutDecisionTree(branchName, branchBase);
        healLegContextArtifacts();
    } finally {
        branchSetup.restoreFreshInput(runCommandForProbes, stashed);
    }
}

function action(params) {
    try {
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var customParams = resolveActionCustomParams(params);
        var ticketKey = params.ticket.key;
        var branchName = configLoader.resolveBranchName(config, params.ticket, 'development');

        console.log('Setting up branch for ticket:', ticketKey, '→', branchName);

        configureGitAuthor(config);
        fetchTargetBranch(config);

        // In two-branch mode, ensure feature branch exists before creating dev branch
        var branchBase = config.git.baseBranch;
        if (config.git.featureBranch && config.git.featureBranch.enabled) {
            branchBase = establishFeatureBranch(config, customParams, params.ticket);
        }

        checkoutDevBranch(branchName, branchBase);

        console.log('Branch ready:', branchName);

    } catch (error) {
        console.error('Error in checkoutBranch:', error);
        // Non-fatal: log but do not block CLI execution
    }
}

// Guarded export — dmtools invokes the top-level `action` global directly as a
// preCliJSAction, but exposing it via module.exports also lets unit tests load this file
// in isolation (see js/unit-tests/test_checkoutBranch.js).
if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        // gh-1190: seam helpers exposed for direct characterization tests.
        resolveActionCustomParams: resolveActionCustomParams,
        configureGitAuthor: configureGitAuthor,
        fetchTargetBranch: fetchTargetBranch,
        readLocalBranchList: readLocalBranchList,
        probeRemoteBranch: probeRemoteBranch,
        createFeatureBranch: createFeatureBranch,
        establishFeatureBranch: establishFeatureBranch,
        checkoutDevBranch: checkoutDevBranch,
        dropUntrackedInputArtifacts: dropUntrackedInputArtifacts
    };
}

/**
 * Shared branch-setup helpers for the pre-CLI setup actions and branch checkout.
 *
 * Why this exists (gh-1247): checkoutBranch.js, preCliDevelopmentSetup.js,
 * preCliTestAutomationSetup.js, preCliStoryTestAutomationSetup.js,
 * preCliMobileTestAutomationSetup.js, preCliTestReworkSetup.js and
 * prepareTestPRForReview.js each carried their own copy of the same
 * branch/marker/setup logic (author config, targeted fetches, branch probes,
 * two-branch feature setup, .git/info/exclude guards, conflict guidance, PR
 * lookups), which the duplication gate flagged at 2-20% per file. The canonical
 * implementations live here ONCE; each action keeps a thin local delegate so
 * its exact commands, log lines and order are unchanged (characterization
 * suites pin them).
 *
 * Design constraints:
 * - ZERO requires on purpose: every collaborator (prHelper, configLoader) is
 *   passed in by the caller, so unit tests can load this module without a
 *   require map and callers keep full control over mock injection.
 * - GraalJS-safe: `var` + plain functions only.
 *
 * Conventions:
 * - `exec(command)` runs ONE git/shell command (through the caller's own
 *   cli_execute_command wrapper, including its workingDirectory handling) and
 *   returns the raw output.
 * - `warnMessage` parameters are optional: pass null for the silent probes.
 */

/**
 * Best-effort git author configuration — failures are warnings only.
 * `logSuccess` keeps checkoutBranch.js's legacy 'Configured git author' line;
 * every other caller passes false (they never logged success).
 */
function configureGitAuthor(exec, config, logSuccess) {
    try {
        exec('git config user.name "' + config.git.authorName + '"');
        exec('git config user.email "' + config.git.authorEmail + '"');
        if (logSuccess) console.log('Configured git author');
    } catch (e) {
        console.warn('Failed to configure git author:', e);
    }
}

/** Targeted origin fetch of exactly `branchNames` — failures are warnings only. */
function fetchBranchRefs(prHelper, exec, branchNames, warnMessage) {
    try {
        var targetedFetch = prHelper.buildTargetedOriginFetchCommand(branchNames);
        if (targetedFetch) exec(targetedFetch);
    } catch (e) {
        console.warn(warnMessage, e);
    }
}

/**
 * `git branch --list` capture for `branchName`, cleaned of wrapper artifacts.
 * `warnMessage` (optional) is logged with the error when the probe fails —
 * pass null for the silent two-branch feature probes.
 */
function readLocalBranchList(prHelper, exec, branchName, warnMessage) {
    try {
        return prHelper.cleanCommandOutput(exec('git branch --list "' + branchName + '"') || '');
    } catch (e) {
        if (warnMessage) console.warn(warnMessage, e);
        return '';
    }
}

/** Strict ls-remote existence probe (gh-912) — `warnMessage` optional. */
function probeRemoteBranch(prHelper, exec, workingDir, branchName, warnMessage) {
    try {
        return prHelper.remoteBranchExists(exec, workingDir, branchName);
    } catch (e) {
        if (warnMessage) console.warn(warnMessage, e);
        return false;
    }
}

/**
 * Two-branch mode: make the feature branch exist — via the configured
 * branchCreateFnPath hook (project-specific mechanism, e.g. an external CI
 * job; the hook is responsible for making the branch exist on origin, so it
 * is fetched and checked out like any other pre-existing remote branch) or
 * the caller's plain-creation tail (`createPlain(featureBranchName)`), which
 * differs per action (checkout+pull vs explicit refspec fetch + checkout -B).
 */
function createFeatureBranch(prHelper, configLoader, exec, config, customParams, ticket, featureBranchName, createPlain) {
    var branchCreateFn = customParams.branchCreateFnPath
        ? configLoader.loadHookFn(customParams.branchCreateFnPath, 'branchCreateFnPath')
        : null;
    if (branchCreateFn) {
        console.log('Two-branch mode: delegating feature branch creation to', customParams.branchCreateFnPath, '→', featureBranchName);
        branchCreateFn({
            branchName: featureBranchName,
            baseBranch: config.git.baseBranch,
            workingDir: config.workingDir,
            ticket: ticket,
            config: config
        });
        exec(prHelper.buildOriginFetchCommand());
        exec('git checkout -b ' + featureBranchName + ' origin/' + featureBranchName);
    } else {
        console.log('Two-branch mode: creating feature branch from', config.git.baseBranch + ':', featureBranchName);
        createPlain(featureBranchName);
    }
}

/**
 * Two-branch mode: ensure the feature branch exists and check it out.
 * Returns the feature branch name — the dev branch is created from it.
 * `createPlain(featureBranchName)` is the no-hook creation tail (see
 * createFeatureBranch).
 */
function establishFeatureBranch(prHelper, configLoader, exec, workingDir, config, customParams, ticket, createPlain) {
    var featureBranchName = configLoader.resolveBranchName(config, ticket, 'feature');
    var featureLocal = readLocalBranchList(prHelper, exec, featureBranchName, null);
    var featureRemoteExists = probeRemoteBranch(prHelper, exec, workingDir, featureBranchName, null);
    var route = prHelper.decideFeatureBranchRoute(featureLocal.trim(), featureRemoteExists);
    if (route === 'create') {
        createFeatureBranch(prHelper, configLoader, exec, config, customParams, ticket, featureBranchName, createPlain);
    } else if (route === 'checkout-remote') {
        exec('git checkout -b ' + featureBranchName + ' origin/' + featureBranchName);
    } else {
        exec('git checkout ' + featureBranchName);
    }
    console.log('Two-branch mode: dev branch will be created from feature branch:', featureBranchName);
    return featureBranchName;
}

/** True when any trimmed line of `lines` equals `entry`. */
function hasExcludeEntry(lines, entry) {
    for (var i = 0; i < lines.length; i++) {
        if (lines[i].trim() === entry) return true;
    }
    return false;
}

/**
 * Ensure `entry` (e.g. 'outputs/', '.codegraph/') is listed in the target
 * repo's .git/info/exclude — local-only, never committed, idempotent.
 * `commentLine` documents WHY the entry must stay untracked; `warnMessage`
 * identifies the caller in the non-fatal failure log.
 */
function ensureGitInfoExclude(entry, commentLine, warnMessage) {
    try {
        var content = '';
        try { content = file_read({ path: '.git/info/exclude' }) || ''; } catch (e) { content = ''; }
        if (hasExcludeEntry(content.split('\n'), entry)) return;
        var sep = content && content.charAt(content.length - 1) !== '\n' ? '\n' : '';
        file_write({
            path: '.git/info/exclude',
            content: content + sep + '\n' + commentLine + '\n' + entry + '\n'
        });
    } catch (e) {
        console.warn(warnMessage, e);
    }
}

// ── gh-1318: fresh leg input/ stash — fresh regenerated context must win ────
// The tracker regenerates input/ before every leg; a branch that already
// carries an ask-mode WIP snapshot of the OLD input/ either refuses checkout
// ("untracked working tree files would be overwritten") or gets the fresh
// copy cleaned away and serves the stale pre-answer copy to the agent. The
// fresh copy is stashed aside (mv, not cp — instant, no duplicate storage)
// for the duration of branch setup and overlaid back afterwards, exactly
// like the .codegraph guard. Recover-first: a setup that crashed between
// stash and restore left the backup dir holding the only fresh copy.
// Commands go through `bash -c` (builtins/rm/mv/test are not in the
// cli_execute_command whitelist); one action per call — the metacharacter
// guard forbids `;`/`&&` even inside the quotes.

/** Backup dir name — hidden, outside input/, seeded into the local excludes. */
var INPUT_STASH_DIR = '.input.branch-setup-bak';

/** True when `dir` exists in the exec's working directory (probe failure = absent). */
function testDirectoryExists(exec, dir) {
    try {
        exec('bash -c "test -d ' + dir + '"');
        return true;
    } catch (e) {
        return false;
    }
}

/**
 * Move the freshly regenerated input/ aside for the duration of branch setup.
 * Returns true when the stash is in place (callers must restore afterwards);
 * false when there was nothing to stash or the move failed — the caller then
 * degrades to its pre-guard behavior (clean/checkout as before), never a
 * throw: a broken guard must not break branch setup.
 *
 * Crash window: a previous setup that died between stash and restore left
 * INPUT_STASH_DIR holding the ONLY copy of the fresh input/ (input/ itself
 * absent). That backup already IS the stash — it stays put and the restore
 * moves it back into place; re-stashing a recovered copy would just churn
 * two renames.
 */
function stashFreshInput(exec) {
    if (testDirectoryExists(exec, 'input')) {
        try {
            exec('bash -c "rm -rf ' + INPUT_STASH_DIR + '"');
            exec('bash -c "mv input ' + INPUT_STASH_DIR + '"');
            return true;
        } catch (e) {
            console.warn('Could not stash fresh input/ before branch setup:', e);
            return false;
